[
  {
    "source_id": "gd_62910120eddcf7bd006407f6",
    "claim": "Launching too early can be detrimental to a startup.",
    "support_span": "Launching Too Early. This paid off with press, PR, partners, etc. But we should have made the product better and waited 3-5 more months before public launch.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_62910120eddcf7bd006407f6",
    "claim": "Insufficient diligence can lead to poor investment decisions.",
    "support_span": "Insufficient Diligence. While I thought I understood the market we were attempting to create and attack, with time, I realized I didn’t fully research comps as deeply or successfully as I could have.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_62910120eddcf7bd006407f6",
    "claim": "Turning down extra Series A funds can be detrimental to a startup.",
    "support_span": "Turning Down Extra Series A Funds That Were Offered and That We Ended Up Needing. I ran it probably too lean, not so much to avoid dilution, but I guess, to maintain control in some fashion.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4e03396df89ad1049c88ccc6",
    "claim": "Major releases happen infrequently in a startup.",
    "support_span": "Things at the beginning and even later are sort of … slooow. Yes, lots is always seemingly going on at a start-up. But the reality is, major releases happen only a few times a year.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4e03396df89ad1049c88ccc6",
    "claim": "Bootstrapping can be slow.",
    "support_span": "Bootstrapping can be mind-numbingly slow.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4e03396df89ad1049c88ccc6",
    "claim": "Small teams can be fraught with drama.",
    "support_span": "Far more people and human issues than you’d expect. Small teams can be very rewarding, but also fraught with drama.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4cb0b1f099da12e7bc82db73",
    "claim": "Bootstrapping is harder to set and enforce firm goals.",
    "support_span": "#1: It’s Harder to Set and Enforce Firm Goals When Bootstrapping. I mean, you can set them, but a certain amount of urgency is lost when you aren’t depending on outside investors, VCs, a board, etc.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4cb0b1f099da12e7bc82db73",
    "claim": "Folks from venture-backed environments prefer working in venture-backed environments.",
    "support_span": "#2. Most folks that have come from a venture-backed environment don’t really want to work somewhere bootstrapped",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_4cb0b1f099da12e7bc82db73",
    "claim": "Crappy revenue isn't worth it when bootstrapping.",
    "support_span": "4. Crappy Revenue Isn’t Worth It. A zero-margin product has little value when bootstrapping.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_01c4f3dd39890d28a5dfedd6",
    "claim": "The challenge of building a business can be addictive.",
    "support_span": "3. The Challenge Keeps You Going. Building a business is hard. It’s frustrating, exhausting, and sometimes feels impossible. But it’s also intellectually stimulating.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_01c4f3dd39890d28a5dfedd6",
    "claim": "Founders can fail multiple times before succeeding.",
    "support_span": "You keep trying because you’re not ready to quit. You haven’t hit the point where you feel like you’ve given it everything you’ve got.",
    "claim_type": "fact"
  },
  {
    "source_id": "gd_01c4f3dd39890d28a5dfedd6",
    "claim": "Belief in one's ability to build something lasting can be a powerful motivator.",
    "support_span": "Your “why” might not be crystal clear yet, and that’s okay. But here’s a thought: maybe your why is simply the belief that you can build something lasting.",
    "claim_type": "fact"
  }
]
